(function () {
  window.DENO_DOC_SEARCH_INDEX = {"kind":"search","nodes":[{"id":"namespace_cidrv4fromcidrv64mapped","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"cidrv4FromCidrv64Mapped","file":"4to6.ts","doc":"Converts an IPv4-mapped IPv6 CIDR block to its IPv4 CIDR representation.The IPv4 address is extracted from the ::ffff:0:0/96 prefix and the prefix length is reduced by 96: an IPv6 /104 becomes an IPv4 /8.","url":"./4to6.ts/~/cidrv4FromCidrv64Mapped.html","deprecated":false},{"id":"namespace_cidrv4tocidrv64mapped","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"cidrv4ToCidrv64Mapped","file":"4to6.ts","doc":"Converts an IPv4 CIDR block to its IPv4-mapped IPv6 CIDR representation.The address is embedded into the ::ffff:0:0/96 prefix and the prefix length is offset by 96: an IPv4 /8 becomes an IPv6 /104.","url":"./4to6.ts/~/cidrv4ToCidrv64Mapped.html","deprecated":false},{"id":"namespace_ipv4from64mapped","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"ipv4From64Mapped","file":"4to6.ts","doc":"Extracts the IPv4 address from an IPv4-mapped IPv6 address.Takes a 128-bit IPv4-mapped IPv6 address (::ffff:x.x.x.x) and returns the embedded 32-bit IPv4 address as defined in RFC 4291 Section 2.5.5.2.","url":"./4to6.ts/~/ipv4From64Mapped.html","deprecated":false},{"id":"namespace_ipv4to64mapped","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"ipv4To64Mapped","file":"4to6.ts","doc":"Converts an IPv4 address to its IPv4-mapped IPv6 representation.Embeds the 32-bit IPv4 address into the ::ffff:0:0/96 prefix, producing the 128-bit IPv4-mapped IPv6 address defined in RFC 4291 Section 2.5.5.2.","url":"./4to6.ts/~/ipv4To64Mapped.html","deprecated":false},{"id":"namespace_iptoarpa","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"ipToArpa","file":"arpa.ts","doc":"Builds the reverse DNS pointer name of an IP address of either version.Picks the version from the type of the address — number for IPv4, bigint for IPv6 — the same typeof dispatch stringifyIp and ipToBytes use, and delegates to ipv4ToArpa or ipv6ToArpa.The name is relative — it carries no trailing dot. Append \".\" if a resolver requires an absolute name.An address that came from parseIp as ::ffff:x.x.x.x arrives here already unwrapped to IPv4 (ADR 0004), so it gets an in-addr.arpa name. Callers wanting the ip6.arpa name of a mapped address hold the bigint from parseIpv6 and call ipv6ToArpa.","url":"./arpa.ts/~/ipToArpa.html","deprecated":false},{"id":"namespace_ipv4toarpa","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"ipv4ToArpa","file":"arpav4.ts","doc":"Builds the reverse DNS pointer name of an IPv4 address.The four octets are written in reverse order under in-addr.arpa, as RFC 1035 §3.5 specifies.The name is relative — it carries no trailing dot. Append \".\" if a resolver requires an absolute name.","url":"./arpav4.ts/~/ipv4ToArpa.html","deprecated":false},{"id":"namespace_ipv6toarpa","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"ipv6ToArpa","file":"arpav6.ts","doc":"Builds the reverse DNS pointer name of an IPv6 address.All 32 nibbles of the expanded address are written in reverse order, one per label, under ip6.arpa, as RFC 3596 §2.5 specifies. Nothing is compressed and no leading zero is elided — the name always has 34 labels.The name is relative — it carries no trailing dot. Append \".\" if a resolver requires an absolute name.An IPv4-mapped address reaches this function only when the caller holds it as a bigint, in which case it gets the ip6.arpa name of its 128-bit value. ipToArpa never sees one, since parseIp unwraps mapped addresses to IPv4 (see ADR 0004).","url":"./arpav6.ts/~/ipv6ToArpa.html","deprecated":false},{"id":"namespace_ipfrombytes","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"ipFromBytes","file":"bytes.ts","doc":"Reads an IPv4 or IPv6 address from a buffer, picking the version from its length.bytes must be exactly 4 bytes (read as IPv4, returning number) or exactly 16 (read as IPv6, returning bigint). Any other length throws a RangeError rather than guessing.There is deliberately no offset parameter. An offset would make the width depend on how much data happens to trail the field rather than on the caller's intent — a 4-byte address 8 bytes from the end of a frame would read as IPv4, and the same field in the same position would read as IPv6 the day the frame grew. Pass the exact bytes instead, with packet.subarray(12, 16), which is a non-copying view; or, when the version is already known, use ipv4FromBytes or ipv6FromBytes, which do take an offset because their width comes from the function rather than from the buffer.Unlike parseIp, this does not unwrap IPv4-mapped addresses. Sixteen bytes always return a bigint, so that ipToBytes(ipFromBytes(b)).length === b.length. Callers wanting the dual-stack normalization compose ipv4From64Mapped explicitly.","url":"./bytes.ts/~/ipFromBytes.html","deprecated":false},{"id":"namespace_iptobytes","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"ipToBytes","file":"bytes.ts","doc":"Writes an IPv4 or IPv6 address, either into a fresh buffer or into one you supply.The width comes from the type of address — 4 bytes for a number, 16 for a bigint — the same typeof dispatch stringifyIp uses. The address is written in network order (big-endian), and the return value is always exactly the bytes written, so result.length tells you the width. When into is given the return is a view into it, never the whole of it.","url":"./bytes.ts/~/ipToBytes.html","deprecated":false},{"id":"namespace_ipv4frombytes","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"ipv4FromBytes","file":"bytesv4.ts","doc":"Reads a 4-byte IPv4 address from a buffer.The four bytes at offset are read in network order (big-endian) and combined into the 32-bit unsigned integer representation used throughout this package.","url":"./bytesv4.ts/~/ipv4FromBytes.html","deprecated":false},{"id":"namespace_ipv4tobytes","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"ipv4ToBytes","file":"bytesv4.ts","doc":"Writes a 4-byte IPv4 address, either into a fresh buffer or into one you supply.The address is written in network order (big-endian). The return value is always exactly the four bytes written: a fresh Uint8Array when into is omitted, and a view into into when it is given — never the whole of into. Writing through that view writes into into.","url":"./bytesv4.ts/~/ipv4ToBytes.html","deprecated":false},{"id":"namespace_ipv6frombytes","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"ipv6FromBytes","file":"bytesv6.ts","doc":"Reads a 16-byte IPv6 address from a buffer.The sixteen bytes at offset are read in network order (big-endian) and combined into the 128-bit bigint representation used throughout this package. IPv4-mapped byte sequences (::ffff:x.x.x.x) are returned as the full 128-bit value, not unwrapped to a number.","url":"./bytesv6.ts/~/ipv6FromBytes.html","deprecated":false},{"id":"namespace_ipv6tobytes","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"ipv6ToBytes","file":"bytesv6.ts","doc":"Writes a 16-byte IPv6 address, either into a fresh buffer or into one you supply.The address is written in network order (big-endian) as four 32-bit chunks. The return value is always exactly the sixteen bytes written: a fresh Uint8Array when into is omitted, and a view into into when it is given — never the whole of into. Writing through that view writes into into.","url":"./bytesv6.ts/~/ipv6ToBytes.html","deprecated":false},{"id":"namespace_addressorcidr","kind":[{"char":"T","kind":"TypeAlias","title":"Type Alias"}],"name":"AddressOrCidr","file":"cidr.ts","doc":"An IP address or a CIDR block, of either IP version.This is a union of Address and Cidr — everything the universal parse and stringify from @hertzg/ip accept and return. Narrow with a typeof check to split the address half from the CIDR half, then use isCidrv4 and isCidrv6 on the latter.","url":"./cidr.ts/~/AddressOrCidr.html","deprecated":false},{"id":"namespace_cidr","kind":[{"char":"T","kind":"TypeAlias","title":"Type Alias"}],"name":"Cidr","file":"cidr.ts","doc":"A CIDR block of either IP version.This is a union of Cidrv4 and Cidrv6, useful for functions that operate on CIDR blocks regardless of IP version. Use the isCidrv4 and isCidrv6 type guards to narrow.","url":"./cidr.ts/~/Cidr.html","deprecated":false},{"id":"namespace_cidraddresses","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"cidrAddresses","file":"cidr.ts","doc":"Generates all addresses in an IPv4 CIDR block.","url":"./cidr.ts/~/cidrAddresses.html","deprecated":false},{"id":"namespace_cidrcontains","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"cidrContains","file":"cidr.ts","doc":"Checks if a CIDR block contains an address.Dispatches to cidrv4Contains or cidrv6Contains based on the address type. Unlike cidrContainsCidr, a version mismatch does not throw — an IPv6 address is not contained in an IPv4 CIDR block, and the reverse, so both return false. The address usually arrives from the network while the CIDR comes from configuration, which makes a mismatch ordinary traffic on a dual-stack listener rather than a caller mistake.IPv4-mapped IPv6 addresses are not converted here. parseIp already unwraps them, so an address from parseIp matches an IPv4 CIDR; one from parseIpv6 stays a bigint and does not.","url":"./cidr.ts/~/cidrContains.html","deprecated":false},{"id":"namespace_cidrcontainscidr","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"cidrContainsCidr","file":"cidr.ts","doc":"Checks if one CIDR block fully contains another.Dispatches to cidrv4ContainsCidr or cidrv6ContainsCidr based on the address type. Throws TypeError when mixing IPv4 and IPv6 CIDRs.","url":"./cidr.ts/~/cidrContainsCidr.html","deprecated":false},{"id":"namespace_cidrfirstaddress","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"cidrFirstAddress","file":"cidr.ts","doc":"Returns the first address of a CIDR block.Dispatches to cidrv4FirstAddress or cidrv6FirstAddress based on the address type. Masking a non-canonical block through this is the version-agnostic way to canonicalize it.There is deliberately no universal cidrFirstUsableAddress: the addresses an operator may assign differ per version, and IPv6 has no library-wide rule to apply. The usable-address vocabulary is IPv4-only — see cidrv4FirstUsableAddress.","url":"./cidr.ts/~/cidrFirstAddress.html","deprecated":false},{"id":"namespace_cidrintersect","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"cidrIntersect","file":"cidr.ts","doc":"Returns the intersection of two CIDR blocks.Dispatches to cidrv4Intersect or cidrv6Intersect based on the address type. Throws TypeError when mixing IPv4 and IPv6 CIDRs.","url":"./cidr.ts/~/cidrIntersect.html","deprecated":false},{"id":"namespace_cidrlastaddress","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"cidrLastAddress","file":"cidr.ts","doc":"Returns the last address of a CIDR block.Dispatches to cidrv4LastAddress or cidrv6LastAddress based on the address type. Together with cidrFirstAddress this gives the numeric bounds of a block without knowing its version — the pair sorting, range comparison, and interval arithmetic want.Note the versions differ in what the last address means: for IPv4 it is the directed broadcast address and is not assignable (cidrv4BroadcastAddress), while IPv6 has no broadcast address and the last address is assignable.","url":"./cidr.ts/~/cidrLastAddress.html","deprecated":false},{"id":"namespace_cidrmerge","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"cidrMerge","file":"cidr.ts","doc":"Merges CIDR blocks into the minimal covering set.Dispatches to cidrv4Merge or cidrv6Merge based on the address type of the first element. All elements must be the same IP version.","url":"./cidr.ts/~/cidrMerge.html","deprecated":false},{"id":"namespace_cidroverlaps","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"cidrOverlaps","file":"cidr.ts","doc":"Checks if two CIDR blocks overlap (share at least one address).Dispatches to cidrv4Overlaps or cidrv6Overlaps based on the address type. Throws TypeError when mixing IPv4 and IPv6 CIDRs.","url":"./cidr.ts/~/cidrOverlaps.html","deprecated":false},{"id":"namespace_cidrsize","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"cidrSize","file":"cidr.ts","doc":"Returns the total number of addresses in a CIDR block.Dispatches to cidrv4Size or cidrv6Size based on the address type.","url":"./cidr.ts/~/cidrSize.html","deprecated":false},{"id":"namespace_cidrsubtract","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"cidrSubtract","file":"cidr.ts","doc":"Subtracts one CIDR block from another.Dispatches to cidrv4Subtract or cidrv6Subtract based on the address type. Throws TypeError when mixing IPv4 and IPv6 CIDRs.","url":"./cidr.ts/~/cidrSubtract.html","deprecated":false},{"id":"namespace_comparecidr","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"compareCidr","file":"cidr.ts","doc":"Compares two CIDR blocks of either version for sorting.The order is version-first and total: every Cidrv4 sorts before every Cidrv6, and within a version blocks sort by address ascending, then by prefix length ascending — the shorter prefix (the larger block) first. Mixed-version arguments are not an error: unlike the other universal CIDR operations in this module, this function never throws, because sorting a mixed list is the reason it exists. Ordering a disjoint union needs no cross-version conversion — see ADR 0005.The block is ordered as written: the address field is compared as stored, without applying the network mask first. See compareCidrv4 for what that means for blocks carrying host bits.","url":"./cidr.ts/~/compareCidr.html","deprecated":false},{"id":"namespace_iscidrv4","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"isCidrv4","file":"cidr.ts","doc":"Type guard that checks whether a Cidr is an IPv4 CIDR block.","url":"./cidr.ts/~/isCidrv4.html","deprecated":false},{"id":"namespace_iscidrv6","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"isCidrv6","file":"cidr.ts","doc":"Type guard that checks whether a Cidr is an IPv6 CIDR block.","url":"./cidr.ts/~/isCidrv6.html","deprecated":false},{"id":"namespace_parsecidr","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"parseCidr","file":"cidr.ts","doc":"Parses an IPv4 or IPv6 CIDR notation string.Detects the IP version by checking for : in the input — if present, the CIDR is parsed as IPv6 (returning Cidrv6), otherwise as IPv4 (returning Cidrv4). IPv4-mapped IPv6 CIDRs with prefix length >= 96 (e.g., ::ffff:192.168.1.0/120) are automatically unwrapped to their IPv4 CIDR representation.To preserve the full IPv6 CIDR for mapped addresses, use parseCidrv6 directly instead.","url":"./cidr.ts/~/parseCidr.html","deprecated":false},{"id":"namespace_stringifycidr","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"stringifyCidr","file":"cidr.ts","doc":"Stringifies a Cidrv4 or Cidrv6 to CIDR notation.","url":"./cidr.ts/~/stringifyCidr.html","deprecated":false},{"id":"namespace_cidrv4","kind":[{"char":"T","kind":"TypeAlias","title":"Type Alias"}],"name":"Cidrv4","file":"cidrv4.ts","doc":"Represents an IPv4 CIDR block.Contains only the parsed values from the CIDR notation.","url":"./cidrv4.ts/~/Cidrv4.html","deprecated":false},{"id":"namespace_cidrv4","kind":[{"char":"p","kind":"Property","title":"Property"}],"name":"Cidrv4.address","file":"cidrv4.ts","doc":"The IPv4 address from the CIDR notation","url":"./cidrv4.ts/~/Cidrv4.address.html","deprecated":false},{"id":"namespace_cidrv4","kind":[{"char":"p","kind":"Property","title":"Property"}],"name":"Cidrv4.prefixLength","file":"cidrv4.ts","doc":"The prefix length (0-32)","url":"./cidrv4.ts/~/Cidrv4.prefixLength.html","deprecated":false},{"id":"namespace_cidrv4addresses","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"cidrv4Addresses","file":"cidrv4.ts","doc":"Generates a range of IP addresses from a CIDR block.Yields IP addresses starting at the specified offset from the network address. The offset is relative to the network address (offset 0 = network address). The step parameter controls the increment (positive or negative) between consecutive addresses. Only addresses within the CIDR block are yielded.By default (when count is not specified), iterates through all addresses in the CIDR block from the offset to the boundary (broadcast for positive step, network for negative step).","url":"./cidrv4.ts/~/cidrv4Addresses.html","deprecated":false},{"id":"namespace_cidrv4broadcastaddress","kind":[{"char":"v","kind":"Variable","title":"Variable"}],"name":"cidrv4BroadcastAddress","file":"cidrv4.ts","doc":"Returns the directed broadcast address of a CIDR block.The broadcast address is the block's last address — the one whose host part is all ones. It addresses every machine on the subnet at once, so it is not assignable to an interface (RFC 1812 section 5.3.5); cidrv4LastUsableAddress is the last address that is. The exception is a /31 or /32, where the whole block is assignable.Same address as cidrv4LastAddress, under the IPv4 name for it. IPv6 has no broadcast address at all, so there is deliberately no cidrv6BroadcastAddress to pair with this one.","url":"./cidrv4.ts/~/cidrv4BroadcastAddress.html","deprecated":false},{"id":"namespace_cidrv4contains","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"cidrv4Contains","file":"cidrv4.ts","doc":"Checks if an IPv4 address is contained within a CIDR block.","url":"./cidrv4.ts/~/cidrv4Contains.html","deprecated":false},{"id":"namespace_cidrv4containscidr","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"cidrv4ContainsCidr","file":"cidrv4.ts","doc":"Checks if one IPv4 CIDR block fully contains another.Returns true when every address in inner is also in outer. This is the case when outer has a shorter-or-equal prefix and both network addresses agree under the outer mask.","url":"./cidrv4.ts/~/cidrv4ContainsCidr.html","deprecated":false},{"id":"namespace_cidrv4firstaddress","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"cidrv4FirstAddress","file":"cidrv4.ts","doc":"Returns the first address of a CIDR block (network address).","url":"./cidrv4.ts/~/cidrv4FirstAddress.html","deprecated":false},{"id":"namespace_cidrv4firstusableaddress","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"cidrv4FirstUsableAddress","file":"cidrv4.ts","doc":"Returns the first assignable address of a CIDR block.This is the cidrv4NetworkAddress plus one, because the network address names the subnet rather than a machine on it (RFC 1812 section 5.3.5).Two prefix lengths are exceptions and yield the network address itself:/31 — a point-to-point link, where RFC 3021 assigns both addresses to the two ends and there is no broadcast address to reserve./32 — a host route, which is a single address and nothing else.Every IPv4 block therefore has at least one assignable address, so this never returns a value outside the block and never has to signal \"none\".","url":"./cidrv4.ts/~/cidrv4FirstUsableAddress.html","deprecated":false},{"id":"namespace_cidrv4intersect","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"cidrv4Intersect","file":"cidrv4.ts","doc":"Returns the intersection of two IPv4 CIDR blocks.Since CIDR blocks are power-of-2-aligned, two overlapping blocks always have a containment relationship -- the intersection is the more specific (longer prefix) block with its canonical network address.","url":"./cidrv4.ts/~/cidrv4Intersect.html","deprecated":false},{"id":"namespace_cidrv4lastaddress","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"cidrv4LastAddress","file":"cidrv4.ts","doc":"Returns the last address of a CIDR block (broadcast address for IPv4).","url":"./cidrv4.ts/~/cidrv4LastAddress.html","deprecated":false},{"id":"namespace_cidrv4lastusableaddress","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"cidrv4LastUsableAddress","file":"cidrv4.ts","doc":"Returns the last assignable address of a CIDR block.This is the cidrv4BroadcastAddress minus one, because the broadcast address addresses the whole subnet rather than a machine on it (RFC 1812 section 5.3.5).Two prefix lengths are exceptions and yield the broadcast address itself:/31 — a point-to-point link, where RFC 3021 assigns both addresses to the two ends and there is no broadcast address to reserve./32 — a host route, which is a single address and nothing else.","url":"./cidrv4.ts/~/cidrv4LastUsableAddress.html","deprecated":false},{"id":"namespace_cidrv4mask","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"cidrv4Mask","file":"cidrv4.ts","doc":"Creates a network mask from an IPv4 prefix length.The prefix length must be between 0 and 32 (inclusive).","url":"./cidrv4.ts/~/cidrv4Mask.html","deprecated":false},{"id":"namespace_cidrv4masktoprefixlength","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"cidrv4MaskToPrefixLength","file":"cidrv4.ts","doc":"Recovers the prefix length from an IPv4 network mask given as a 32-bit unsigned integer.","url":"./cidrv4.ts/~/cidrv4MaskToPrefixLength.html","deprecated":false},{"id":"namespace_cidrv4merge","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"cidrv4Merge","file":"cidrv4.ts","doc":"Merges IPv4 CIDR blocks into the minimal covering set.Takes an array of possibly overlapping, adjacent, or redundant CIDR blocks and returns the minimal set of non-overlapping CIDR prefix blocks covering the exact same address space.","url":"./cidrv4.ts/~/cidrv4Merge.html","deprecated":false},{"id":"namespace_cidrv4networkaddress","kind":[{"char":"v","kind":"Variable","title":"Variable"}],"name":"cidrv4NetworkAddress","file":"cidrv4.ts","doc":"Returns the network address of a CIDR block.The network address is the block's first address — the one whose host part is all zeros. It names the subnet itself rather than a machine on it, so it is not assignable to an interface (RFC 1812 section 5.3.5); cidrv4FirstUsableAddress is the first address that is. The exception is a /31 or /32, where the whole block is assignable.Same address as cidrv4FirstAddress, under the IPv4 name for it. IPv6 has no counterpart to the cidrv4BroadcastAddress half of this pair, which is why the cidrv6 side stays with first/last only.","url":"./cidrv4.ts/~/cidrv4NetworkAddress.html","deprecated":false},{"id":"namespace_cidrv4overlaps","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"cidrv4Overlaps","file":"cidrv4.ts","doc":"Checks if two IPv4 CIDR blocks overlap (share at least one address).Two CIDRs overlap when one contains at least one address of the other. This is equivalent to checking containment using the shorter prefix. The check is symmetric: cidrv4Overlaps(a, b) === cidrv4Overlaps(b, a).","url":"./cidrv4.ts/~/cidrv4Overlaps.html","deprecated":false},{"id":"namespace_cidrv4size","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"cidrv4Size","file":"cidrv4.ts","doc":"Returns the total number of IP addresses in a CIDR block.For a /24 network, this returns 256. For a /32, this returns 1.","url":"./cidrv4.ts/~/cidrv4Size.html","deprecated":false},{"id":"namespace_cidrv4subtract","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"cidrv4Subtract","file":"cidrv4.ts","doc":"Subtracts one IPv4 CIDR block from another.Returns the minimal set of CIDR blocks representing all IP addresses in a but not in b. The algorithm recursively splits a into two halves at prefix+1, keeping the non-overlapping half and recursing into the overlapping half.","url":"./cidrv4.ts/~/cidrv4Subtract.html","deprecated":false},{"id":"namespace_cidrv4usableaddresses","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"cidrv4UsableAddresses","file":"cidrv4.ts","doc":"Generates every assignable address in a CIDR block, in ascending order.Yields cidrv4FirstUsableAddress through cidrv4LastUsableAddress inclusive — cidrv4UsableSize addresses in total, with the network and broadcast addresses skipped except at /31 and /32 where the whole block is assignable.Lazy: nothing is materialized, so a short prefix costs nothing until the caller iterates it.Unlike cidrv4Addresses this takes no offset, count, or step — its extent is fixed by the block. Reach for cidrv4Addresses to slice a block on any other terms.","url":"./cidrv4.ts/~/cidrv4UsableAddresses.html","deprecated":false},{"id":"namespace_cidrv4usablesize","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"cidrv4UsableSize","file":"cidrv4.ts","doc":"Returns the number of assignable addresses in a CIDR block.This is cidrv4Size minus the network and broadcast addresses, except at /31 and /32 where the whole block is assignable — see cidrv4FirstUsableAddress. Writing cidrv4Size(cidr) - 2 by hand gets 0 for a /31 and -1 for a /32, which is why this is a function rather than a note in the docs.The result is never zero: every IPv4 block has at least one assignable address.","url":"./cidrv4.ts/~/cidrv4UsableSize.html","deprecated":false},{"id":"namespace_comparecidrv4","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"compareCidrv4","file":"cidrv4.ts","doc":"Compares two IPv4 CIDR blocks for sorting.Orders by address ascending, then by prefix length ascending — so where two blocks share a start address, the shorter prefix (the larger block, the supernet) sorts first. This is the order PostgreSQL's cidr type uses, and the order every containing block needs to precede the blocks it contains, which is what cidrv4Merge relies on internally.The block is ordered as written: the address field is compared as stored, without applying the network mask first. A block carrying host bits therefore sorts by the address stringifyCidrv4 will print for it, and 10.0.0.5/24 does not compare equal to 10.0.0.0/24 even though they cover the same addresses. Normalize with cidrv4NetworkAddress first if that is the order you want.","url":"./cidrv4.ts/~/compareCidrv4.html","deprecated":false},{"id":"namespace_parsecidrv4","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"parseCidrv4","file":"cidrv4.ts","doc":"Parses an IPv4 CIDR notation string to a Cidrv4 object.Returns only the parsed values (address and prefix length).","url":"./cidrv4.ts/~/parseCidrv4.html","deprecated":false},{"id":"namespace_stringifycidrv4","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"stringifyCidrv4","file":"cidrv4.ts","doc":"Stringifies a Cidrv4 object to CIDR notation.","url":"./cidrv4.ts/~/stringifyCidrv4.html","deprecated":false},{"id":"namespace_cidrv6","kind":[{"char":"T","kind":"TypeAlias","title":"Type Alias"}],"name":"Cidrv6","file":"cidrv6.ts","doc":"Represents an IPv6 CIDR block.Contains only the parsed values from the CIDR notation.","url":"./cidrv6.ts/~/Cidrv6.html","deprecated":false},{"id":"namespace_cidrv6","kind":[{"char":"p","kind":"Property","title":"Property"}],"name":"Cidrv6.address","file":"cidrv6.ts","doc":"The IPv6 address from the CIDR notation","url":"./cidrv6.ts/~/Cidrv6.address.html","deprecated":false},{"id":"namespace_cidrv6","kind":[{"char":"p","kind":"Property","title":"Property"}],"name":"Cidrv6.prefixLength","file":"cidrv6.ts","doc":"The prefix length (0-128)","url":"./cidrv6.ts/~/Cidrv6.prefixLength.html","deprecated":false},{"id":"namespace_cidrv6addresses","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"cidrv6Addresses","file":"cidrv6.ts","doc":"Generates a range of IP addresses from a CIDR block.Yields IP addresses starting at the specified offset from the network address. The offset is relative to the network address (offset 0 = network address). The step parameter controls the increment (positive or negative) between consecutive addresses. Only addresses within the CIDR block are yielded.By default (when count is not specified), iterates through all addresses in the CIDR block from the offset to the boundary (last address for positive step, network for negative step).IPv6 blocks can be enormous. A /64 has 2^64 addresses. Use count or iterate lazily to avoid memory issues.","url":"./cidrv6.ts/~/cidrv6Addresses.html","deprecated":false},{"id":"namespace_cidrv6contains","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"cidrv6Contains","file":"cidrv6.ts","doc":"Checks if an IPv6 address is contained within a CIDR block.","url":"./cidrv6.ts/~/cidrv6Contains.html","deprecated":false},{"id":"namespace_cidrv6containscidr","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"cidrv6ContainsCidr","file":"cidrv6.ts","doc":"Checks if one IPv6 CIDR block fully contains another.Returns true when every address in inner is also in outer. This is the case when outer has a shorter-or-equal prefix and both network addresses agree under the outer mask.","url":"./cidrv6.ts/~/cidrv6ContainsCidr.html","deprecated":false},{"id":"namespace_cidrv6firstaddress","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"cidrv6FirstAddress","file":"cidrv6.ts","doc":"Returns the first address of a CIDR block.IPv6 has no equivalent of the IPv4 network address, so unlike cidrv4FirstAddress this is normally assignable to an interface. The one caveat is per-link rather than universal: RFC 4291 section 2.6.1 reserves the all-zeros interface identifier as the Subnet-Router anycast address, while RFC 6164 assigns both addresses of a /127 inter-router link.Because that reservation depends on the link, there is deliberately no cidrv6FirstUsableAddress to pair with cidrv4FirstUsableAddress. Callers whose link does reserve the anycast skip it themselves — see the second example.","url":"./cidrv6.ts/~/cidrv6FirstAddress.html","deprecated":false},{"id":"namespace_cidrv6intersect","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"cidrv6Intersect","file":"cidrv6.ts","doc":"Returns the intersection of two IPv6 CIDR blocks.Since CIDR blocks are power-of-2-aligned, two overlapping blocks always have a containment relationship -- the intersection is the more specific (longer prefix) block with its canonical network address.","url":"./cidrv6.ts/~/cidrv6Intersect.html","deprecated":false},{"id":"namespace_cidrv6lastaddress","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"cidrv6LastAddress","file":"cidrv6.ts","doc":"Returns the last address of a CIDR block.IPv6 has no broadcast address, so nothing is reserved at the top of a block and this address is assignable. That is why there is deliberately no cidrv6BroadcastAddress and no cidrv6LastUsableAddress to pair with their IPv4 counterparts — the asymmetry is a fact about IPv6, not a gap.","url":"./cidrv6.ts/~/cidrv6LastAddress.html","deprecated":false},{"id":"namespace_cidrv6mask","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"cidrv6Mask","file":"cidrv6.ts","doc":"Creates a network mask from an IPv6 prefix length.The prefix length must be between 0 and 128 (inclusive).","url":"./cidrv6.ts/~/cidrv6Mask.html","deprecated":false},{"id":"namespace_cidrv6masktoprefixlength","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"cidrv6MaskToPrefixLength","file":"cidrv6.ts","doc":"Recovers the prefix length from an IPv6 network mask given as a bigint.","url":"./cidrv6.ts/~/cidrv6MaskToPrefixLength.html","deprecated":false},{"id":"namespace_cidrv6merge","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"cidrv6Merge","file":"cidrv6.ts","doc":"Merges IPv6 CIDR blocks into the minimal covering set.Takes an array of possibly overlapping, adjacent, or redundant CIDR blocks and returns the minimal set of non-overlapping CIDR prefix blocks covering the exact same address space.","url":"./cidrv6.ts/~/cidrv6Merge.html","deprecated":false},{"id":"namespace_cidrv6overlaps","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"cidrv6Overlaps","file":"cidrv6.ts","doc":"Checks if two IPv6 CIDR blocks overlap (share at least one address).Two CIDRs overlap when one contains at least one address of the other. This is equivalent to checking containment using the shorter prefix. The check is symmetric: cidrv6Overlaps(a, b) === cidrv6Overlaps(b, a).","url":"./cidrv6.ts/~/cidrv6Overlaps.html","deprecated":false},{"id":"namespace_cidrv6size","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"cidrv6Size","file":"cidrv6.ts","doc":"Returns the total number of IP addresses in a CIDR block.For a /120 network, this returns 256n. For a /128, this returns 1n. The result is a bigint because IPv6 blocks can hold up to 2^128 addresses.","url":"./cidrv6.ts/~/cidrv6Size.html","deprecated":false},{"id":"namespace_cidrv6subtract","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"cidrv6Subtract","file":"cidrv6.ts","doc":"Subtracts one IPv6 CIDR block from another.Returns the minimal set of CIDR blocks representing all IP addresses in a but not in b. The algorithm recursively splits a into two halves at prefix+1, keeping the non-overlapping half and recursing into the overlapping half.","url":"./cidrv6.ts/~/cidrv6Subtract.html","deprecated":false},{"id":"namespace_comparecidrv6","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"compareCidrv6","file":"cidrv6.ts","doc":"Compares two IPv6 CIDR blocks for sorting.Orders by address ascending, then by prefix length ascending — so where two blocks share a start address, the shorter prefix (the larger block, the supernet) sorts first. This is the order PostgreSQL's cidr type uses, and the order every containing block needs to precede the blocks it contains, which is what cidrv6Merge relies on internally.The block is ordered as written: the address field is compared as stored, without applying the network mask first. A block carrying host bits therefore sorts by the address stringifyCidrv6 will print for it, and 2001:db8::5/64 does not compare equal to 2001:db8::/64 even though they cover the same addresses. Normalize with cidrv6FirstAddress first if that is the order you want.","url":"./cidrv6.ts/~/compareCidrv6.html","deprecated":false},{"id":"namespace_parsecidrv6","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"parseCidrv6","file":"cidrv6.ts","doc":"Parses an IPv6 CIDR notation string to a Cidrv6 object.Returns only the parsed values (address and prefix length).","url":"./cidrv6.ts/~/parseCidrv6.html","deprecated":false},{"id":"namespace_stringifycidrv6","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"stringifyCidrv6","file":"cidrv6.ts","doc":"Stringifies a Cidrv6 object to CIDR notation.","url":"./cidrv6.ts/~/stringifyCidrv6.html","deprecated":false},{"id":"namespace_classifiedip","kind":[{"char":"T","kind":"TypeAlias","title":"Type Alias"}],"name":"ClassifiedIp","file":"classify.ts","doc":"Result of classifying an IP address with version information and parsed value.Discriminated union on kind:\"ipv4\" — see ClassifiedIpv4\"ipv6\" — see ClassifiedIpv6","url":"./classify.ts/~/ClassifiedIp.html","deprecated":false},{"id":"namespace_classifiedipv4","kind":[{"char":"T","kind":"TypeAlias","title":"Type Alias"}],"name":"ClassifiedIpv4","file":"classify.ts","doc":"Result of classifying an IPv4 address.Contains the parsed value, the kind discriminant \"ipv4\", and the classification label from ClassificationIpv4.","url":"./classify.ts/~/ClassifiedIpv4.html","deprecated":false},{"id":"namespace_classifiedipv4","kind":[{"char":"p","kind":"Property","title":"Property"}],"name":"ClassifiedIpv4.kind","file":"classify.ts","doc":"","url":"./classify.ts/~/ClassifiedIpv4.kind.html","deprecated":false},{"id":"namespace_classifiedipv4","kind":[{"char":"p","kind":"Property","title":"Property"}],"name":"ClassifiedIpv4.value","file":"classify.ts","doc":"","url":"./classify.ts/~/ClassifiedIpv4.value.html","deprecated":false},{"id":"namespace_classifiedipv4","kind":[{"char":"p","kind":"Property","title":"Property"}],"name":"ClassifiedIpv4.classification","file":"classify.ts","doc":"","url":"./classify.ts/~/ClassifiedIpv4.classification.html","deprecated":false},{"id":"namespace_classifiedipv6","kind":[{"char":"T","kind":"TypeAlias","title":"Type Alias"}],"name":"ClassifiedIpv6","file":"classify.ts","doc":"Result of classifying an IPv6 address.Contains the parsed value, the kind discriminant \"ipv6\", and the classification label from ClassificationIpv6.","url":"./classify.ts/~/ClassifiedIpv6.html","deprecated":false},{"id":"namespace_classifiedipv6","kind":[{"char":"p","kind":"Property","title":"Property"}],"name":"ClassifiedIpv6.kind","file":"classify.ts","doc":"","url":"./classify.ts/~/ClassifiedIpv6.kind.html","deprecated":false},{"id":"namespace_classifiedipv6","kind":[{"char":"p","kind":"Property","title":"Property"}],"name":"ClassifiedIpv6.value","file":"classify.ts","doc":"","url":"./classify.ts/~/ClassifiedIpv6.value.html","deprecated":false},{"id":"namespace_classifiedipv6","kind":[{"char":"p","kind":"Property","title":"Property"}],"name":"ClassifiedIpv6.classification","file":"classify.ts","doc":"","url":"./classify.ts/~/ClassifiedIpv6.classification.html","deprecated":false},{"id":"namespace_classifyip","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"classifyIp","file":"classify.ts","doc":"Classifies an IPv4 address into its well-known range.","url":"./classify.ts/~/classifyIp.html","deprecated":false},{"id":"namespace_classificationipv4","kind":[{"char":"T","kind":"TypeAlias","title":"Type Alias"}],"name":"ClassificationIpv4","file":"classifyv4.ts","doc":"All possible IPv4 address classification labels.Returned by classifyIpv4 to identify which well-known range an IPv4 address belongs to.","url":"./classifyv4.ts/~/ClassificationIpv4.html","deprecated":false},{"id":"namespace_classifyipv4","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"classifyIpv4","file":"classifyv4.ts","doc":"Classifies an IPv4 address into its well-known range.Returns the most specific classification label for the given address. Every valid 32-bit unsigned integer maps to exactly one classification.","url":"./classifyv4.ts/~/classifyIpv4.html","deprecated":false},{"id":"namespace_isipv4benchmarking","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"isIpv4Benchmarking","file":"classifyv4.ts","doc":"Checks if an IPv4 address is in the benchmarking range (RFC 2544).Benchmarking range: 198.18.0.0/15 (198.18.0.0 – 198.19.255.255)","url":"./classifyv4.ts/~/isIpv4Benchmarking.html","deprecated":false},{"id":"namespace_isipv4broadcast","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"isIpv4Broadcast","file":"classifyv4.ts","doc":"Checks if an IPv4 address is the limited broadcast address.Broadcast address: 255.255.255.255","url":"./classifyv4.ts/~/isIpv4Broadcast.html","deprecated":false},{"id":"namespace_isipv4cgnat","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"isIpv4CgNat","file":"classifyv4.ts","doc":"Checks if an IPv4 address is in the Carrier-Grade NAT range (RFC 6598).CG-NAT range: 100.64.0.0/10 (100.64.0.0 – 100.127.255.255)","url":"./classifyv4.ts/~/isIpv4CgNat.html","deprecated":false},{"id":"namespace_isipv4documentation","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"isIpv4Documentation","file":"classifyv4.ts","doc":"Checks if an IPv4 address is in a documentation range (RFC 5737).Documentation ranges:192.0.2.0/24 (TEST-NET-1)198.51.100.0/24 (TEST-NET-2)203.0.113.0/24 (TEST-NET-3)","url":"./classifyv4.ts/~/isIpv4Documentation.html","deprecated":false},{"id":"namespace_isipv4linklocal","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"isIpv4LinkLocal","file":"classifyv4.ts","doc":"Checks if an IPv4 address is a link-local address (RFC 3927).Link-local range: 169.254.0.0/16 (169.254.0.0 – 169.254.255.255)","url":"./classifyv4.ts/~/isIpv4LinkLocal.html","deprecated":false},{"id":"namespace_isipv4loopback","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"isIpv4Loopback","file":"classifyv4.ts","doc":"Checks if an IPv4 address is a loopback address (RFC 1122).Loopback range: 127.0.0.0/8 (127.0.0.0 – 127.255.255.255)","url":"./classifyv4.ts/~/isIpv4Loopback.html","deprecated":false},{"id":"namespace_isipv4multicast","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"isIpv4Multicast","file":"classifyv4.ts","doc":"Checks if an IPv4 address is a multicast address (RFC 5771).Multicast range: 224.0.0.0/4 (224.0.0.0 – 239.255.255.255)","url":"./classifyv4.ts/~/isIpv4Multicast.html","deprecated":false},{"id":"namespace_isipv4private","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"isIpv4Private","file":"classifyv4.ts","doc":"Checks if an IPv4 address is in a private range (RFC 1918).Private ranges:10.0.0.0/8 (10.0.0.0 – 10.255.255.255)172.16.0.0/12 (172.16.0.0 – 172.31.255.255)192.168.0.0/16 (192.168.0.0 – 192.168.255.255)","url":"./classifyv4.ts/~/isIpv4Private.html","deprecated":false},{"id":"namespace_isipv4public","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"isIpv4Public","file":"classifyv4.ts","doc":"Checks if an IPv4 address is a public (globally routable) address.Returns true if the address does not belong to any well-known special-purpose range (private, loopback, link-local, multicast, reserved, broadcast, this-network, CG-NAT, benchmarking, or documentation).","url":"./classifyv4.ts/~/isIpv4Public.html","deprecated":false},{"id":"namespace_isipv4reserved","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"isIpv4Reserved","file":"classifyv4.ts","doc":"Checks if an IPv4 address is in the reserved range (RFC 1112).Reserved range: 240.0.0.0/4 (240.0.0.0 – 255.255.255.254), excluding the broadcast address 255.255.255.255.","url":"./classifyv4.ts/~/isIpv4Reserved.html","deprecated":false},{"id":"namespace_isipv4thisnetwork","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"isIpv4ThisNetwork","file":"classifyv4.ts","doc":"Checks if an IPv4 address is in the \"this network\" range (RFC 791).This network range: 0.0.0.0/8 (0.0.0.0 – 0.255.255.255)","url":"./classifyv4.ts/~/isIpv4ThisNetwork.html","deprecated":false},{"id":"namespace_classificationipv6","kind":[{"char":"T","kind":"TypeAlias","title":"Type Alias"}],"name":"ClassificationIpv6","file":"classifyv6.ts","doc":"All possible IPv6 address classification labels.Returned by classifyIpv6 to identify which well-known range an IPv6 address belongs to.","url":"./classifyv6.ts/~/ClassificationIpv6.html","deprecated":false},{"id":"namespace_classifyipv6","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"classifyIpv6","file":"classifyv6.ts","doc":"Classifies an IPv6 address into its well-known range.Returns the most specific classification label for the given address. For overlapping ranges (e.g., 2001:db8::/32 within 2001::/32 within 2000::/3), the most specific match is returned.","url":"./classifyv6.ts/~/classifyIpv6.html","deprecated":false},{"id":"namespace_isipv6benchmarking","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"isIpv6Benchmarking","file":"classifyv6.ts","doc":"Checks if an IPv6 address is in the benchmarking range (RFC 5180).Benchmarking range: 2001:2::/48","url":"./classifyv6.ts/~/isIpv6Benchmarking.html","deprecated":false},{"id":"namespace_isipv6documentation","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"isIpv6Documentation","file":"classifyv6.ts","doc":"Checks if an IPv6 address is in the documentation range (RFC 3849).Documentation range: 2001:db8::/32","url":"./classifyv6.ts/~/isIpv6Documentation.html","deprecated":false},{"id":"namespace_isipv6globalunicast","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"isIpv6GlobalUnicast","file":"classifyv6.ts","doc":"Checks if an IPv6 address is a global unicast address (RFC 4291).Global unicast range: 2000::/3 (2000:: – 3fff:ffff:...:ffff)Note: This includes sub-ranges like documentation (2001:db8::/32), Teredo (2001::/32), and benchmarking (2001:2::/48). Use the more specific classifiers or classifyIpv6 to distinguish them.","url":"./classifyv6.ts/~/isIpv6GlobalUnicast.html","deprecated":false},{"id":"namespace_isipv6ipv4mapped","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"isIpv6Ipv4Mapped","file":"classifyv6.ts","doc":"Checks if an IPv6 address is an IPv4-mapped address (RFC 4291).IPv4-mapped range: ::ffff:0:0/96 (::ffff:0.0.0.0 – ::ffff:255.255.255.255)","url":"./classifyv6.ts/~/isIpv6Ipv4Mapped.html","deprecated":false},{"id":"namespace_isipv6ipv4translated","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"isIpv6Ipv4Translated","file":"classifyv6.ts","doc":"Checks if an IPv6 address is an IPv4-translated address (RFC 6052).IPv4-translated range: 64:ff9b::/96Used by NAT64 for IPv4/IPv6 translation.","url":"./classifyv6.ts/~/isIpv6Ipv4Translated.html","deprecated":false},{"id":"namespace_isipv6linklocal","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"isIpv6LinkLocal","file":"classifyv6.ts","doc":"Checks if an IPv6 address is a link-local address (RFC 4291).Link-local range: fe80::/10 (fe80:: – febf:ffff:...:ffff)","url":"./classifyv6.ts/~/isIpv6LinkLocal.html","deprecated":false},{"id":"namespace_isipv6loopback","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"isIpv6Loopback","file":"classifyv6.ts","doc":"Checks if an IPv6 address is the loopback address (RFC 4291).Loopback: ::1","url":"./classifyv6.ts/~/isIpv6Loopback.html","deprecated":false},{"id":"namespace_isipv6multicast","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"isIpv6Multicast","file":"classifyv6.ts","doc":"Checks if an IPv6 address is a multicast address (RFC 4291).Multicast range: ff00::/8 (ff00:: – ffff:ffff:...:ffff)","url":"./classifyv6.ts/~/isIpv6Multicast.html","deprecated":false},{"id":"namespace_isipv6orchidv2","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"isIpv6Orchidv2","file":"classifyv6.ts","doc":"Checks if an IPv6 address is an ORCHIDv2 address (RFC 7343).ORCHIDv2 range: 2001:20::/28","url":"./classifyv6.ts/~/isIpv6Orchidv2.html","deprecated":false},{"id":"namespace_isipv6teredo","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"isIpv6Teredo","file":"classifyv6.ts","doc":"Checks if an IPv6 address is a Teredo address (RFC 4380).Teredo range: 2001::/32Note: This overlaps with documentation (2001:db8::/32), benchmarking (2001:2::/48), and ORCHIDv2 (2001:20::/28) ranges. Use classifyIpv6 for the most specific classification.","url":"./classifyv6.ts/~/isIpv6Teredo.html","deprecated":false},{"id":"namespace_isipv6uniquelocal","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"isIpv6UniqueLocal","file":"classifyv6.ts","doc":"Checks if an IPv6 address is a unique local address (RFC 4193).Unique local range: fc00::/7 (fc00:: – fdff:ffff:...:ffff)This is the IPv6 equivalent of IPv4 private addresses (RFC 1918).","url":"./classifyv6.ts/~/isIpv6UniqueLocal.html","deprecated":false},{"id":"namespace_isipv6unspecified","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"isIpv6Unspecified","file":"classifyv6.ts","doc":"Checks if an IPv6 address is the unspecified address (RFC 4291).Unspecified: ::","url":"./classifyv6.ts/~/isIpv6Unspecified.html","deprecated":false},{"id":"namespace_address","kind":[{"char":"T","kind":"TypeAlias","title":"Type Alias"}],"name":"Address","file":"ip.ts","doc":"A plain IP address of either IP version.This is a union of number (IPv4, 32-bit) and bigint (IPv6, 128-bit) — the JS primitive type is what carries the version. Useful for functions that operate on addresses regardless of IP version; narrow with a typeof check.","url":"./ip.ts/~/Address.html","deprecated":false},{"id":"namespace_compareip","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"compareIp","file":"ip.ts","doc":"Compares two IP addresses of either version for sorting.The order is version-first and total: every IPv4 address (number) sorts before every IPv6 address (bigint), and within a version addresses sort numerically ascending. Mixed-version arguments are not an error — unlike the universal CIDR operations, this function never throws, because sorting a mixed dual-stack list is the reason it exists. Go's net/netip, Rust's std::net::IpAddr and PostgreSQL's inet all order addresses the same way.Note that \"IPv4 sorts first\" is a statement about order, not about magnitude: the two address spaces are disjoint and nothing is converted between them. An IPv4-mapped address held as a bigint is an IPv6 value and sorts in the IPv6 half — see the example below. In practice parseIp already unwraps mapped addresses to their IPv4 number form, so a mapped bigint only reaches this function via parseIpv6.","url":"./ip.ts/~/compareIp.html","deprecated":false},{"id":"namespace_parseip","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"parseIp","file":"ip.ts","doc":"Parses an IPv4 or IPv6 address string to its numeric representation.Detects the IP version by checking for : in the input — if present, the address is parsed as IPv6 (returning bigint), otherwise as IPv4 (returning number). IPv4-mapped IPv6 addresses (::ffff:x.x.x.x) are automatically unwrapped to their IPv4 number representation.To preserve the full IPv6 bigint for mapped addresses, use parseIpv6 directly instead.","url":"./ip.ts/~/parseIp.html","deprecated":false},{"id":"namespace_stringifyip","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"stringifyIp","file":"ip.ts","doc":"Stringifies an IPv4 (number) or IPv6 (bigint) address to its standard notation.IPv4 addresses (numbers) are always stringified as dotted decimal. Since parseIp unwraps IPv4-mapped IPv6 addresses to numbers, round-tripping a mapped address through parseIp/stringifyIp produces the IPv4 form (e.g. \"192.168.1.1\", not \"::ffff:c0a8:101\").To produce the mapped IPv6 representation, use ipv4To64Mapped with stringifyIpv6:","url":"./ip.ts/~/stringifyIp.html","deprecated":false},{"id":"namespace_compareipv4","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"compareIpv4","file":"ipv4.ts","doc":"Compares two IPv4 addresses for sorting, numerically ascending.Suitable as an Array.prototype.sort / toSorted comparator. For a comparator that also accepts IPv6 addresses, see compareIp, which sorts every IPv4 address before every IPv6 one.","url":"./ipv4.ts/~/compareIpv4.html","deprecated":false},{"id":"namespace_parseipv4","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"parseIpv4","file":"ipv4.ts","doc":"Parses an IPv4 address in dotted decimal notation to a number.The function validates the format and range of each octet. Leading zeros are not allowed (except for \"0\" itself).","url":"./ipv4.ts/~/parseIpv4.html","deprecated":false},{"id":"namespace_stringifyipv4","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"stringifyIpv4","file":"ipv4.ts","doc":"Stringifies a number to an IPv4 address in dotted decimal notation.The number must represent a valid 32-bit unsigned integer (0 to 4294967295).","url":"./ipv4.ts/~/stringifyIpv4.html","deprecated":false},{"id":"namespace_compareipv6","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"compareIpv6","file":"ipv6.ts","doc":"Compares two IPv6 addresses for sorting, numerically ascending.Suitable as an Array.prototype.sort / toSorted comparator. For a comparator that also accepts IPv4 addresses, see compareIp, which sorts every IPv4 address before every IPv6 one.IPv4-mapped addresses (::ffff:x.x.x.x) are ordinary IPv6 values here — they sort by their 128-bit value, inside the ::ffff:0:0/96 block.","url":"./ipv6.ts/~/compareIpv6.html","deprecated":false},{"id":"namespace_compressipv6","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"compressIpv6","file":"ipv6.ts","doc":"Compresses an IPv6 address to its shortest canonical form.This is equivalent to parsing and re-stringifying the address, which produces the canonical compressed representation.","url":"./ipv6.ts/~/compressIpv6.html","deprecated":false},{"id":"namespace_expandipv6","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"expandIpv6","file":"ipv6.ts","doc":"Expands an IPv6 address to its full uncompressed form.Returns the address with all 8 groups fully specified with 4 hex digits each. This is equivalent to parsing the address and re-stringifying it with stringifyIpv6Expanded.","url":"./ipv6.ts/~/expandIpv6.html","deprecated":false},{"id":"namespace_parseipv6","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"parseIpv6","file":"ipv6.ts","doc":"Parses an IPv6 address in colon-hexadecimal notation to a bigint.Supports standard IPv6 formats:Full form: 2001:0db8:0000:0000:0000:0000:0000:0001Compressed form with ::: 2001:db8::1Mixed IPv4 form: ::ffff:192.168.1.1Zone IDs are stripped: fe80::1%eth0 becomes fe80::1","url":"./ipv6.ts/~/parseIpv6.html","deprecated":false},{"id":"namespace_stringifyipv6","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"stringifyIpv6","file":"ipv6.ts","doc":"Stringifies a bigint to an IPv6 address in compressed colon-hexadecimal notation.The output uses the canonical compressed form:Leading zeros in each group are omittedThe longest run of consecutive all-zero groups is replaced with ::If there are multiple runs of the same length, the first one is compressed","url":"./ipv6.ts/~/stringifyIpv6.html","deprecated":false},{"id":"namespace_stringifyipv6expanded","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"stringifyIpv6Expanded","file":"ipv6.ts","doc":"Stringifies a bigint to an IPv6 address in full uncompressed colon-hexadecimal notation.Every one of the 8 groups is written with all 4 hex digits, and no run of zero groups is replaced with ::. This is the counterpart of stringifyIpv6, which produces the canonical compressed form, and the bigint-taking counterpart of expandIpv6, which takes a string.","url":"./ipv6.ts/~/stringifyIpv6Expanded.html","deprecated":false},{"id":"namespace_parse","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"parse","file":"mod.ts","doc":"Parses an IP address or CIDR notation string.Detects CIDR notation by checking for /. If present, delegates to parseCidr; otherwise delegates to parseIp. The IP version (IPv4 vs IPv6) is auto-detected within each delegate.","url":"./mod.ts/~/parse.html","deprecated":false},{"id":"namespace_stringify","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"stringify","file":"mod.ts","doc":"Stringifies an IPv4 address (number) to dotted decimal notation.","url":"./mod.ts/~/stringify.html","deprecated":false},{"id":"namespace_isvalidcidr","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"isValidCidr","file":"validate.ts","doc":"Checks if a string is valid IPv4 or IPv6 CIDR notation.","url":"./validate.ts/~/isValidCidr.html","deprecated":false},{"id":"namespace_isvalidip","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"isValidIp","file":"validate.ts","doc":"Checks if a string is a valid plain IP address (IPv4 or IPv6).Does not accept CIDR notation — use isValidCidr for that.","url":"./validate.ts/~/isValidIp.html","deprecated":false},{"id":"namespace_isvalidcidrv4","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"isValidCidrv4","file":"validatev4.ts","doc":"Checks if a string is valid IPv4 CIDR notation.","url":"./validatev4.ts/~/isValidCidrv4.html","deprecated":false},{"id":"namespace_isvalidipv4","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"isValidIpv4","file":"validatev4.ts","doc":"Checks if a string is a valid IPv4 address in dotted decimal notation.","url":"./validatev4.ts/~/isValidIpv4.html","deprecated":false},{"id":"namespace_isvalidcidrv6","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"isValidCidrv6","file":"validatev6.ts","doc":"Checks if a string is valid IPv6 CIDR notation.","url":"./validatev6.ts/~/isValidCidrv6.html","deprecated":false},{"id":"namespace_isvalidipv6","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"isValidIpv6","file":"validatev6.ts","doc":"Checks if a string is a valid IPv6 address in colon-hexadecimal notation.Accepts full form, compressed form with ::, IPv4-mapped addresses (::ffff:192.168.1.1), and addresses with zone IDs (fe80::1%eth0).","url":"./validatev6.ts/~/isValidIpv6.html","deprecated":false},{"id":"namespace_cidrversion","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"cidrVersion","file":"version.ts","doc":"Reports which IP version a CIDR notation string is written in.The CIDR counterpart of ipVersion, with the same contract: 4, 6, or undefined, describing the string rather than the parsed value. A plain address without a prefix length is not CIDR notation.","url":"./version.ts/~/cidrVersion.html","deprecated":false},{"id":"namespace_ipversion","kind":[{"char":"T","kind":"TypeAlias","title":"Type Alias"}],"name":"IpVersion","file":"version.ts","doc":"An IP version number: 4 for IPv4, 6 for IPv6.Returned by ipVersion and cidrVersion, which widen it with undefined for input that is not an address or CIDR block at all.","url":"./version.ts/~/IpVersion.html","deprecated":false},{"id":"namespace_ipversion","kind":[{"char":"f","kind":"Function","title":"Function"}],"name":"ipVersion","file":"version.ts","doc":"Reports which IP version a plain address string is written in.Returns 4 for dotted decimal, 6 for colon-hexadecimal, and undefined for anything else — never 0, so the answer cannot be mistaken for a version number in a numeric context.The answer describes the string, not the value it would parse to. An IPv4-mapped IPv6 address such as ::ffff:10.1.2.3 is written as IPv6 and reports 6, even though parseIp unwraps it to an IPv4 number. Version n always means \"parseIpv4 / parseIpv6 for that version accepts this string\". To get the version of an already parsed value, use typeof — number is IPv4, bigint is IPv6.CIDR notation is not an address — use cidrVersion for that.What counts as valid is exactly what isValidIpv4 and isValidIpv6 accept, which is looser than some other libraries: surrounding whitespace and trailing text are tolerated by the parsers underneath, so ipVersion(\" 10.1.2.3\") is 4.","url":"./version.ts/~/ipVersion.html","deprecated":false}]};
})()